package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamPracticalCritBank1 {
    private const val T = "දෘෂ්ටිකෝණ, මානව ව්‍යුහය, ප්‍රායෝගික මාධ්‍ය හා විචාරය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("රේඛීය දෘෂ්ටිකෝණ චිත්‍රයක (Perspective Drawing) නරඹන්නාගේ ඇස් මට්ටම නියෝජනය කරන තිරස් රේඛාව හඳුන්වන්නේ කුමන නමින්ද?", "ක්ෂිතිජ රේඛාව (Horizon Line)", "අභිසාරී ලක්ෂ්‍යය (Vanishing Point)", "සමෝච්ඡ රේඛාව (Contour Line)", "පාද රේඛාව (Baseline)", "අහසත් පොළොවත් වෙන් වන සේ පෙනෙන ඇස් මට්ටමේ තිරස් රේඛාව ක්ෂිතිජ රේඛාවයි."),
        q("දුම්රිය පීලි දෙකක් හෝ කෙළින් මාවතක් ඈතට යන විට ක්ෂිතිජ රේඛාව මත එකම තැනකට එකතු වී නොපෙනී යන ස්ථානය කුමක්ද?", "අභිසාරී ලක්ෂ්‍යය (Vanishing Point)", "ක්ෂිතිජ මට්ටම (Horizon Line)", "විකර්ණ අක්ෂය (Diagonal Axis)", "නාභිගත මධ්‍යය (Focal Point)", "සමාන්තර රේඛා ඈතට යාමේදී කුඩා වී ක්ෂිතිජ රේඛාව මත හමුවන ලක්ෂ්‍යය Vanishing Point වේ."),
        q("කෙළින් ඉදිරිපසට මුහුණ ලා පිහිටි කාමරයක් හෝ දිගු දුම්රිය මගක් ඇඳීමට වඩාත් සුදුසු දෘෂ්ටිකෝණ ක්‍රමය කුමක්ද?", "ඒකලක්ෂ්‍ය දෘෂ්ටිකෝණය (One-Point Perspective)", "ද්විලක්ෂ්‍ය දෘෂ්ටිකෝණය", "ත්‍රිලක්ෂ්‍ය දෘෂ්ටිකෝණය", "සමමිතික නොවන පැතලි ක්‍රමය", "එක් අභිසාරී ලක්ෂ්‍යයක් පමණක් භාවිත කර ඉදිරිපස තලය නොවෙනස්ව තබා ගැඹුර අඳියි."),
        q("ගොඩනැගිල්ලක කෙළවරක් (Corner) නරඹන්නා දෙසට මුහුණ ලා පිහිටා පැති දෙක දෙපැත්තට ඈත් වී පෙනෙන දසුනක් අඳින ක්‍රමය කුමක්ද?", "ද්විලක්ෂ්‍ය දෘෂ්ටිකෝණය (Two-Point Perspective)", "ඒකලක්ෂ්‍ය දෘෂ්ටිකෝණය", "අඛණ්ඩ ආඛ්‍යාන ක්‍රමය", "පැතලි ද්විමාන ක්‍රමය", "ක්ෂිතිජ රේඛාවේ දෙකෙළවර අභිසාරී ලක්ෂ්‍ය දෙකක් තබා පැති බිත්ති දෙකම ඇඳීම ද්විලක්ෂ්‍ය ක්‍රමයයි."),
        q("උස් ගොඩනැගිල්ලක පාමුල සිට ඉහළට බලන විට (Worm's-eye) හෝ ගුවන් යානයක සිට පහළට බලන විට (Bird's-eye) භාවිත කරන ක්‍රමය කුමක්ද?", "ත්‍රිලක්ෂ්‍ය දෘෂ්ටිකෝණය (Three-Point)", "ඒකලක්ෂ්‍ය දෘෂ්ටිකෝණය (One-Point)", "ද්විලක්ෂ්‍ය දෘෂ්ටිකෝණය (Two-Point)", "පැතලි සමමිතික රේඛා ක්‍රමය (Flat Grid)", "තිරස් අභිසාරී ලක්ෂ්‍ය දෙකට අමතරව උස හෝ ගැඹුර දැක්වීමට තුන්වන ලක්ෂ්‍යයක්ද යොදා ගනී."),
        q("ක්ෂිතිජ රේඛාවට 'ඉහළින්' පිහිටි ඝනකයක (Cube) අපට පෙනෙන මතුපිට පෘෂ්ඨය කුමක්ද?", "ඝනකයේ යටි පැත්ත (Bottom face)", "ඝනකයේ උඩු පැත්ත", "පිටුපස පැත්ත පමණක්", "කිසිම පැත්තක් නොපෙනේ", "අපගේ ඇස් මට්ටමට ඉහළින් ඇති නිසා වස්තුවේ යටි පැත්ත පෙනෙන අතර ඇස් මට්ටමට පහළින් ඇති විට උඩු පැත්ත පෙනේ."),
        q("සම්මත වැඩිහිටි මානව සිරුරක මුළු උස ප්‍රමාණය ඔහුගේ හිසේ උස මෙන් කී ගුණයක් ලෙස සාමාන්‍යයෙන් සලකනු ලැබේද?", "හිස් ප්‍රමාණ 7.5 සිට 8 දක්වා (8-Head Proportion)", "හිස් ප්‍රමාණ 3 ක් පමණි", "හිස් ප්‍රමාණ 15 ක්", "හිස් ප්‍රමාණ 2 ක් පමණි", "සම්භාව්‍ය කලා අධ්‍යයනයේදී වැඩිහිටි සිරුරක් සඳහා හිස් 7.5–8 අනුපාතය ප්‍රධාන මිනුම් දණ්ඩකි."),
        q("සම්මත වැඩිහිටි මානව මුහුණක ඉදිරිපස දසුනේදී 'ඇස් දෙක' පිහිටන්නේ හිසේ සම්පූර්ණ උසෙන් කුමන මට්ටමේද?", "හිස මුදුන හා නිකට අතර හරි මැද (1/2)", "හිස මුදුනට ආසන්න ඉහළ තුනෙන් එක (1/3)", "නිකටට ආසන්න පහළ හතරෙන් එක (1/4)", "නළල හා නාසය අතර ඉහළ තීරුව (1/5)", "බොහෝ ආධුනිකයන් ඇස් ඉහළින් ඇන්දත් හිස්කබල හා හිසකෙස් නිසා ඇස් ඇත්තේ හිසේ හරි මැදය."),
        q("මිනිස් මුහුණේ ඉදිරිපස පෙනුමේදී ඇස් දෙක අතර පවතින සාමාන්‍ය පරතරය කොපමණද?", "එක් ඇසක පළලට සමාන පරතරයක්", "ඇස් තුනක පළලක්", "හිසේ මුළු පළලෙන් භාගයක්", "කිසිදු පරතරයක් නැත", "සාමාන්‍ය මුහුණක පළල ඇස් පහක් පමණ වන අතර ඇස් දෙක මැද එක් ඇසක පළලක ඉඩක් ඇත."),
        q("මිනිස් මුහුණක කන් දෙක සාමාන්‍යයෙන් පිහිටන්නේ කුමන ඉහළ හා පහළ සීමා දෙක අතරද?", "ඇහිබැම මට්ටමේ සිට නාසයේ පහළ කෙළවර මට්ටම දක්වා", "නළල මුදුනේ සිට තොල් යට දක්වා", "ඇස් යට සිට බෙල්ල දක්වා", "හිස මුදුනේ සිට ඇහිබැම දක්වා", "මුහුණ කෙළින් තබා බලන විට කනේ ඉහළ කෙළවර ඇහිබැමටද පහළ කෙළවර නාස් පුඩුවටද සමාන්තර වේ."),
        q("මිනිස් සිරුරක් පූර්ණව ඇඳීමේදී දෙපසට විහිදවූ අත් දෙකේ ඇඟිලි තුඩු අතර දුර සමාන වන්නේ කුමකටද?", "එම පුද්ගලයාගේ සම්පූර්ණ උසට (Height)", "හිසේ උස මෙන් දෙගුණයක ප්‍රමාණයට", "ඉණ සිට පාදයේ වළලුකර දක්වා දිගට", "උරහිස් පළල මෙන් දෙගුණයක ප්‍රමාණයට", "විට්රූවියන් මිනිසාගේ පරිදි දෑත් දෙපසට දිගු කළ විට මුළු දිග ශරීර උසට සමාන වේ."),
        q("ජල සායම් (Watercolour) චිත්‍ර කලාවේ ඇති ප්‍රධානතම විශේෂිත ගුණාංගය කුමක්ද?", "විනිවිද පෙනෙන බව හා කඩදාසි සුද ආලෝකය කිරීම", "ඝන ඇලෙනසුලු තෙල් ස්තර උඩින් උඩ ගැසීම", "අඳුරු තීන්ත මත සුදු තීන්ත ගා එළිය ගැනීම", "පිළිස්සූ මැටි මතුපිට පමණක් ආලේප කිරීම", "විනිවිද පෙනෙන ජල සායම්වල සුදු වර්ණය නොයොදා සුදු කඩදාසියේ ආලෝකය ඉතිරි කිරීම ප්‍රධාන රීතියයි."),
        q("ජල සායම්වල 'වෙට්-ඔන්-වෙට්' (Wet-on-Wet) ශිල්පීය ක්‍රමයේදී සිදු කරන්නේ කුමක්ද?", "තෙත් කඩදාසිය මත තෙත් වර්ණ තවරා මුසු කිරීම", "වියළි කඩදාසියක පින්සලෙන් රළු ඉරි ගැසීම", "උණු කළ මී ඉටි රේඛා ඇඳ ජලය ඉවත් කිරීම", "ඝන පෝස්ටර් තීන්තයෙන් පැතලි දාර සෑදීම", "අහස, වලාකුළු හා මීදුම වැනි මෘදු දාර අවශ්‍ය පසුබිම් මැවීමට වෙට්-ඔන්-වෙට් ක්‍රමය යොදයි."),
        q("ජල සායම් හා පෝස්ටර් වර්ණ (Poster Paint / Gouache) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "ජල සායම් විනිවිද පෙනෙන (Transparent) අතර පෝස්ටර් වර්ණ පාරාන්ධ (Opaque) වේ", "පෝස්ටර් වර්ණ තෙල්වලින් දිය කරයි", "ජල සායම් කිසිදා වතුරෙන් දිය නොවේ", "පෝස්ටර් වර්ණවල සුදු පාට නැත", "පෝස්ටර් වර්ණ යට තීන්ත ස්තරය වසා දමන බැවින් අකුරු හා පැතලි ග්‍රැෆික් නිර්මාණවලට සුදුසුය."),
        q("පැන්සල් වර්ගීකරණයේදී 'H' (Hard) සහ 'B' (Black/Soft) අකුරුවලින් අදහස් කරන්නේ කුමක්ද?", "H යනු තද ලා පැහැති මිනිරන් වන අතර B යනු මෘදු තද කළු පැහැති මිනිරන් වේ", "H යනු රතු හා B යනු නිල් වේ", "H යනු ජල සායම් හා B යනු තෙල් සායම් වේ", "දෙකම එකම තද බවකින් යුක්තය", "සූක්ෂ්ම දළ සටහන්වලට HB/2H ද, ගැඹුරු සෙවණැලි ඇඳීමට 2B, 4B, 6B, 8B පැන්සල්ද යොදා ගනී."),
        q("පහත සඳහන් පැන්සල් ශ්‍රේණි අතරින් වඩාත්ම තද කළු (Darkest) හා මෘදුම සෙවණැලි ලබා දෙන්නේ කුමන පැන්සලද?", "6B හෝ 8B පැන්සල", "2H පැන්සල", "HB පැන්සල", "4H පැන්සල", "B අගය වැඩි වන විට ග්‍රැෆයිට් මෘදු වී මැටි ප්‍රමාණය අඩු වන නිසා තද කළු සෙවණැලි ලැබේ."),
        q("ඇක්‍රිලික් තීන්ත (Acrylic Paint) නූතන චිත්‍ර ශිල්පීන් අතර ඉතා ජනප්‍රිය වීමට ප්‍රධාන හේතුව කුමක්ද?", "ජලයෙන් දිය වී ඉක්මනින් වියළී ස්ථිර වන බැවින්", "සම්පූර්ණයෙන් වියළීමට සති දෙකක් ගත වන බැවින්", "ටර්පන්ටයින් ද්‍රාවකයෙන් පමණක් දිය වන බැවින්", "වියළුණු පසුත් ජලයෙන් පහසුවෙන් සේදිය හැකි බැවින්", "කැන්වස්, ලී, බිත්ති හා රෙදි මත තෙල් සායම් හෝ ජල සායම් මෙන් ඇක්‍රිලික් භාවිත කළ හැකිය."),
        q("තෙල් සායම් (Oil Paint) සිතුවම් ඇඳීමේදී තීන්ත තුනී කිරීමට හා පින්සල් සේදීමට භාවිත කරන ද්‍රාවකය කුමක්ද?", "ටර්පන්ටයින් හෝ හණ තෙල් (Linseed Oil)", "සාමාන්‍ය පිරිසිදු ඇල් ජලය හෝ මිදි යුෂ", "සුදු විනාකිරි හෝ පොල් කුඩු මිශ්‍ර දියර", "ලුණු දියර හෝ කොහොඹ කොළ සාරය", "තෙල් සායම් ජලයේ දිය නොවන අතර හණ තෙල් වර්ණයට දිලිසීමත් ටර්පන්ටයින් තුනී බවත් දෙයි."),
        q("තෙල් සායම් චිත්‍රයක ඉරිතැළීම් වැළැක්වීම සඳහා පිළිපදින මූලික තාක්ෂණික රීතිය කුමක්ද?", "කෙට්ටු මත තරබාරු (Fat over Lean) රීතිය", "තෙත් මත වියළි (Dry over Wet) රීතිය", "තද මත ලා (Light over Dark) රීතිය", "සිසිල් මත උණුසුම් (Warm over Cool) රීතිය", "යට ස්තරයට වඩා උඩ ස්තරයේ තෙල් ප්‍රමාණය වැඩි වූ විට සිතුවම කල් පැවැත්මෙන් ඉහළ වේ."),
        q("තෙල් පැස්ටල් (Oil Pastels) සහ වියළි කූරු හුණු පැස්ටල් (Chalk / Soft Pastels) අතර වෙනස කුමක්ද?", "වියළි පැස්ටල් කුඩු මුසුවන අතර තෙල් පැස්ටල් ඇලේ", "තෙල් පැස්ටල් ජලයේ දියවන අතර වියළි පැස්ටල් දිය නොවේ", "වියළි පැස්ටල්වල තෙල් බහුල අතර තෙල් පැස්ටල් වියළිය", "දෙකම ලෝහ බට තුළ දියර ආකාරයෙන් පමණක් පවතී", "වියළි පැස්ටල් සිතුවම් කුඩු නොහැලීමට අවසානයේ Fixative ඉසිනු ලැබේ."),
        q("දිය කළ නොහැකි ඉටි හෝ තෙල් පැස්ටල්වලින් ඇඳ ඊට උඩින් ජල සායම් ගෑමේ පාසල් හා නිර්මාණාත්මක ශිල්පය කුමක්ද?", "ඉටි ප්‍රතිරෝධී ක්‍රමය (Wax Resist)", "ලිනෝ කැපුම් ක්‍රමය (Linocut)", "මොසැයික් ක්‍රමය (Mosaic)", "කොලාජ් ක්‍රමය (Collage)", "තෙල් හා ජලය මිශ්‍ර නොවන නිසා ඉටි රේඛා ජල සායම් පලවා හැර අලංකාර වයනයක් මවයි."),
        q("චිත්‍ර ශිල්පියෙකු 'චාකෝල්' (Charcoal - ගල් අඟුරු කූරු) මාධ්‍යය වඩාත් ප්‍රිය කරන්නේ කුමන වර්ගයේ සිතුවම් සඳහාද?", "ඉක්මන් ඉරියව් සටහන් හා තද කළු-සුදු ආලේඛ්‍ය", "දීප්තිමත් විනිවිද පෙනෙන ජල සායම් පසුබිම්", "සියුම් වර්ණ චක්‍ර හා පෝස්ටර් අකුරු නිර්මාණ", "උණු ඉටි ආලේපිත රෙදිපිළි බතික් සැලසුම්", "විලෝ චාකෝල් පහසුවෙන් මැකීමට හා තද කළු-අළු පරාසයක් ගැනීමට ඉතා සුදුසුය."),
        q("'ලිනෝ කට්' (Linocut) හෝ 'ලී කුට්ටි මුද්‍රණය' (Woodcut) අයත් වන්නේ කුමන මුද්‍රණ කලා කාණ්ඩයටද?", "උන්නත මුද්‍රණය (Relief Printing - උස් වූ කොටස්වල තීන්ත ගා මුද්‍රණය කිරීම)", "ඉන්ටග්ලියෝ ගැඹුරු මුද්‍රණය", "සිල්ක් ස්ක්‍රීන් සිදුරු මුද්‍රණය", "ලිතොග්‍රැෆි පැතලි මුද්‍රණය", "කැපුම් කටු (Gouge) මගින් සුදු පැහැයට අවශ්‍ය කොටස් කපා ඉවත් කර ඉතිරි උස් කොටස්වල රෝලරයෙන් තීන්ත ගායි."),
        q("ලිනෝ කට් හෝ ලී මුද්‍රණයක් කිරීමේදී මතක තබා ගත යුතු අනිවාර්ය නීතිය කුමක්ද?", "කණ්ණාඩි ප්‍රතිබිම්බයක් සේ අකුරු අනෙක් පසට කැපීම", "සැමවිටම තුනී ජල සායම් තීන්ත පමණක් ආලේප කිරීම", "කැපීමෙන් පසු මුද්‍රණ තහඩුව ගින්නෙන් පිළිස්සීම", "අකුරු හා රූප සෘජු ලෙස කෙළින්ම තහඩුවේ කැපීම", "කඩදාසිය තහඩුව මත තබා ඔබන නිසා වම දකුණ මාරු වන බව සලකා නිර්මාණය කළ යුතුය."),
        q("රෙදිපිළි මත දියර තීන්ත ගලා යාම වැළැක්වීම සඳහා 'උණු කළ මී ඉටි හා පැරෆින් ඉටි' (Wax) යොදා රටා මවන සාම්ප්‍රදායික කලාව කුමක්ද?", "බතික් කලාව (Batik)", "ටයි-ඩයි කලාව", "ස්ටෙන්සිල් කලාව", "ලිනෝ කට්", "ඉටි ගෑ තැනට ඩයි නොවදින අතර වරින් වර ළා පැහැයේ සිට තද පැහැයට ඩයි කර ඉටි උණු වතුරෙන් ඉවත් කරයි."),
        q("බතික් කලාවේදී ඉතා සියුම් ඉටි රේඛා ඇඳීම සඳහා යොදා ගන්නා තඹ නළය හා ලී මිට සහිත විශේෂිත උපකරණය කුමක්ද?", "චැන්ටිං උපකරණය (Tjanting)", "ලිනෝ ගවුජ් කටුව", "බ්‍රේයර් රෝලරය", "පැලට් පිහිය", "උණු ඉටි පුරවා ගත් චැන්ටිං පෑනෙන් රෙද්ද මත සියුම් මෝස්තර ඉරි ඇඳිය හැකිය."),
        q("රෙදිපිළි නූල්වලින් හෝ රබර් පටිවලින් තදින් ගැට ගසා ඩයි වර්ණවල ගිල්වා රවුම් හා රේඛා රටා මවන කලාව කුමක්ද?", "ටයි-ඩයි (Tie-Dye / බන්ධනි)", "සිල්ක් ස්ක්‍රීන්", "මොසැයික්", "ටෙරාකොටා", "ගැට ගැසූ ස්ථානවලට ඩයි ඇතුළු නොවන නිසා සුදු හා විවිධ වර්ණවත් වෘත්ත රටා මැවේ."),
        q("සිදුරු කළ කාඩ්බෝඩ් හෝ ප්ලාස්ටික් පත්‍රයක් (Template) මත තීන්ත තැවරීමෙන් එකම රූපය කිහිප වරක් මුද්‍රණය කරන සරල මුද්‍රණ ශිල්පය කුමක්ද?", "ස්ටෙන්සිල් මුද්‍රණය (Stencil Printing)", "එචිං මුද්‍රණය", "කොයිලිං මැටි ක්‍රමය", "ග්ලේසිං ක්‍රමය", "කැපූ සිදුරු අතරින් ස්පොන්ජ් හෝ ස්ටෙන්සිල් පින්සලෙන් තීන්ත තැවරීමෙන් පෝස්ටර් හා රෙදි සැරසේ."),
        q("වර්තමානයේ ටී-ෂර්ට්, බැනර් හා පෝස්ටර් විශාල ප්‍රමාණයක් මුද්‍රණය කිරීමට සියුම් දැල් රෙද්දක් රාමුවක සවි කර යොදන මුද්‍රණ ක්‍රමය කුමක්ද?", "සිල්ක් ස්ක්‍රීන් මුද්‍රණය (Screen Printing)", "ලී කුට්ටි මුද්‍රණය (Woodblock Printing)", "තඹ තහඩු කැටයම් මුද්‍රණය (Intaglio Etching)", "ලිතොග්‍රැෆි ගල් මුද්‍රණය (Lithography)", "ස්ක්විජී (Squeegee) රබර් පටියෙන් තීන්ත ඇද විවෘත දැල් සිදුරු හරහා රෙද්දට හෝ කඩදාසියට තීන්ත යවයි."),
        q("පෝරණුවක පිළිස්සූ මැටි නිර්මාණයක් 'ටෙරාකොටා' (Terracotta) ලෙස හැඳින්වෙන අතර, අතින් මැටි බඳුනක් තැනීමේ ප්‍රධාන ක්‍රම තුන මොනවාද?", "පින්ච්, කොයිල් (දඟර) සහ ස්ලැබ් (පතුරු) ක්‍රම", "හැචිං, ස්ටිප්ලිං සහ ස්මජිං තාන ක්‍රම", "වෙට්-ඔන්-වෙට් සහ ඩ්‍රයි බ්‍රෂ් ජල සායම් ක්‍රම", "ලිනෝ කට්, එචිං සහ සිල්ක් ස්ක්‍රීන් මුද්‍රණ ක්‍රම", "සකපෝරුව (Potter's Wheel) නොමැතිව අතින් මැටි හැඩගැන්වීමේදී මෙම මූලික ශිල්ප තුන භාවිත කෙරේ."),
        q("මැටි කැබලි දෙකක් (උදා: කෝප්පයක අත සහ බඳ) ශක්තිමත්ව එකට ඇලවීම සඳහා මැටි කලාවේදී භාවිත කරන තාක්ෂණය කුමක්ද?", "ස්කෝර් ඇන්ඩ් ස්ලිප් (ඉරි කපා දියර මැටි ගෑම)", "පෘෂ්ඨ දෙක සිනිඳු කර හණ තෙල් ආලේප කිරීම", "මැටි වියළුණු පසු සාමාන්‍ය කඩදාසි මැලියම් ගෑම", "උණු කළ මී ඉටි තවරා තදින් එක් කිරීම", "සම්බන්ධ කරන පෘෂ්ඨ දෙක සූරා රළු කර දියර මැටි (Slip) තැවරීමෙන් පිළිස්සීමේදී ගැලවී යාම වළකී."),
        q("මැටි කර්මාන්තයේදී 'බිස්ක් පිළිස්සීම' (Bisque Firing) සහ 'ග්ලේස් කිරීම' (Glazing) යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "පළමුව තද කිරීමට පිළිස්සීම හා පසුව ඔප ගා පිළිස්සීම", "අමු මැටි ජලයේ පොඟවා අච්චු තුළ වියළා ගැනීම", "පිළිස්සූ බඳුන් මතුපිට තෙල් සායම් ආලේප කිරීම", "ලී කැටයම් මත කපු රෙදි අලවා ඔප දැමීම", "ග්ලේස් ආලේප කිරීමෙන් මැටි බඳුන ජලය කාන්දු නොවන, පිරිසිදු හා වර්ණවත් නිමාවකට පත් වේ."),
        q("මූර්ති නිර්මාණයේදී 'ආකලන ක්‍රමය' (Additive Sculpture) සහ 'ව්‍යාකලන ක්‍රමය' (Subtractive Sculpture) වෙනස් වන්නේ කෙසේද?", "මැටි එක් කිරීම ආකලනද ගල් කැපීම ව්‍යාකලනද වේ", "ගලට මැටි එක් කිරීම ව්‍යාකලන ක්‍රමය ලෙස හැඳින්වේ", "කඩදාසි ඇලවීම සහ රෙදි මැසීම මෙම ක්‍රම දෙක වේ", "කිසිදු වෙනසක් නැති අතර දෙකම ලෝහ වාත්තුවකි", "කළුගල් බුදු පිළිම Subtractive මූර්ති වන අතර මැටි, ප්ලාස්ටර් හා කඩදාසි පල්ප නිර්මාණ Additive වේ."),
        q("ඉවතලන පැරණි පුවත්පත් පොඟවා මැලියම් සමඟ අඹරා සැහැල්ලු වෙස්මුහුණු හා මූර්ති සෑදීමේ ජනප්‍රිය ශිල්පය කුමක්ද?", "පේපර් මැෂේ (කඩදාසි පල්ප කලාව)", "මොසැයික් (වීදුරු කැබලි ඇතිරීම)", "සිල්ක් ස්ක්‍රීන් (දැල් රෙදි මුද්‍රණය)", "බුවොන් ෆ්‍රෙස්කෝ (තෙත් බදාම චිත්‍ර)", "පාසල් හා රූකඩ/කෝලම් නිර්මාණයේදී පහසු හා පරිසර හිතකාමී ත්‍රිමාණ මාධ්‍යයක් ලෙස මෙය යොදා ගනී."),
        q("විවිධ වර්ණ කඩදාසි, රෙදි කැබලි, කොළපොතු හා ඡායාරූප තලයක් මත ඇලවීමෙන් සිතුවමක් නිර්මාණය කිරීම හඳුන්වන්නේ කෙසේද?", "කොලාජ් (Collage)", "ෆ්‍රෙස්කෝ", "ස්ටිප්ලිං", "එචිං", "ත්‍රිමාණ ඉවතලන ද්‍රව්‍ය හා කැබලි එකතු කර ප්‍රතිමා තැනීම 'ඇසෙම්බ්ලේජ්' (Assemblage) ලෙස හැඳින්වේ."),
        q("කුඩා වර්ණවත් ගල්, ටයිල් කැබලි, බිත්තර කටු හෝ වීදුරු කැබලි එක ළඟ අතුරා සිතුවමක් මැවීමේ කලාව කුමක්ද?", "මොසැයික් (Mosaic)", "බතික්", "ලිනෝ කට්", "ජල සායම්", "පසුබිමට ඇලවූ කුඩා කැබලි (Tesserae) අතර කුඩා හිඩැස් තැබීමෙන් මොසැයික් අලංකාර වේ."),
        q("කලාව රසවිඳීමේ හා විචාරය කිරීමේදී 'එඩ්මන්ඩ් ෆෙල්ඩ්මන්' (Feldman) හඳුන්වා දුන් කලා විචාර පියවර හතර පිළිවෙළින් මොනවාද?", "විස්තර, විශ්ලේෂණ, අර්ථකථන හා විනිශ්චය", "සැලසුම්, ඇඳීම, වර්ණ ගැන්වීම හා රාමු කිරීම", "නිරීක්ෂණ, පිටපත් කිරීම, වෙනස් කිරීම හා ප්‍රදර්ශනය", "තෝරා ගැනීම, මැණීම, කැපීම හා ඔප දැමීම", "කලා කෘතියක් හුදෙක් 'ලස්සනයි' කීම වෙනුවට විද්‍යාත්මකව විචාරය කිරීමට මෙම පියවර 4 යොදා ගනී."),
        q("කලා විචාරයේ පළමු පියවර වන 'විස්තර කිරීම' (Description) යටතේ අප සිදු කරන්නේ කුමක්ද?", "චිත්‍රයේ කලාකරුවා, වර්ෂය, මාධ්‍යය සහ ඇසට පෙනෙන වස්තු කිසිදු මතයකින් තොරව ලැයිස්තුගත කිරීම", "චිත්‍රය හොඳද නරකද කියා තීරණය කිරීම", "චිත්‍රයේ සැඟවුණු දාර්ශනික අර්ථය අනුමාන කිරීම", "වර්ණ චක්‍රයේ නීති විවේචනය කිරීම", "විස්තර කිරීමේදී අප අපගේ පෞද්ගලික කැමැත්ත නොකියා දකින කරුණු (Facts) පමණක් සඳහන් කරයි."),
        q("කලා විචාරයේ දෙවන පියවර වන 'විශ්ලේෂණය' (Analysis) තුළදී පරීක්ෂා කරනු ලබන්නේ කුමක්ද?", "මූලිකාංග හා මූලධර්ම සංවිධානය කර ඇති ආකාරය", "කලා කෘතියේ වර්තමාන වෙන්දේසි වෙළඳපොළ වටිනාකම", "කලාකරුවාගේ උපන් ගම හා පවුල් පසුබිම පිළිබඳ විස්තර", "කෘතිය තැන්පත් කර ඇති කෞතුකාගාරයේ ඉදිකිරීම් වර්ෂය", "වර්ණ සංයෝජනය, සංයුති රිද්මය හා නාභිගත ස්ථානය ක්‍රියාත්මක වන ආකාරය විශ්ලේෂණයෙන් සොයයි."),
        q("කලා විචාරයේ තුන්වන පියවර වන 'අර්ථකථනය' (Interpretation) මගින් සොයා බලන්නේ කුමක්ද?", "කෘතියෙන් කියවෙන අදහස, හැඟීම හා සංකේතාර්ථය", "සිතුවමේ කැන්වසයේ ප්‍රමාණය හා භාවිත කළ පින්සල් අංකය", "චිත්‍රය රාමු කිරීමට ගත් දැව වර්ගය හා බර ප්‍රමාණය", "නිර්මාණය සඳහා වෙළඳපොළෙන් මිලදී ගත් තීන්ත මිල", "දෘශ්‍ය සාක්ෂි මත පදනම්ව චිත්‍රයෙන් කියවෙන මානව හා සමාජීය අරුත මෙහිදී විමසා බලයි."),
        q("කලා විචාරයේ අවසන් පියවර වන 'විනිශ්චය / ඇගයීම' (Judgement / Evaluation) තුළදී සිදු කරන්නේ කුමක්ද?", "සාක්ෂි මත කෘතියේ කලාත්මක සාර්ථකත්වය තීරණය කිරීම", "මුල් කලාකරුවාගේ නම හා වර්ෂය අලුතින් වෙනස් කිරීම", "තීන්ත ස්තරයේ රසායනික සංයුතිය රසායනාගාරයේ පිරික්සීම", "සිතුවමේ මතුපිට ආරක්ෂිත වාර්නිෂ් තට්ටුවක් ආලේප කිරීම", "තාක්ෂණික නිපුණතාව, අදහස් ප්‍රකාශන බලය හා අව්‍යාජ බව අනුව තර්කානුකූල විනිශ්චයක් දෙයි."),
        q("පෝස්ටර් නිර්මාණයේදී (Poster Design) අනුගමනය කළ යුතු ප්‍රධානතම ගුණාංග තුන මොනවාද?", "ආකර්ෂණීය රූපය, කෙටි පැහැදිලි පණිවිඩය (Typography) සහ ඉහළ දෘශ්‍ය ප්‍රතිවිරෝධතාව", "ඉතා කුඩා අකුරින් පිටු දෙකක් ලිවීම", "පසුබිමට සමාන පාටින් අකුරු ලිවීම", "ඡායාරූප 50ක් එක පෝස්ටරයක ඇලවීම", "දුර සිට තත්පර කිහිපයකින් අවබෝධ වන සේ සරල රූප හා පැහැදිලි සිරස්තල පෝස්ටරයක තිබිය යුතුය."),
        q("ලාංඡන නිර්මාණයේදී (Logo / Emblem Design) එය කුඩා මුද්‍රාවක සිට විශාල පුවරුවක් දක්වා භාවිත කිරීමට තිබිය යුතු ගුණය කුමක්ද?", "සරල, මතක හිටින හා එක් වර්ණයෙන් පවා පැහැදිලි හැඩය", "ඉතා සියුම් සංකීර්ණ මල් වැල් සිය ගණනකින් සැරසීම", "වර්ණ ප්‍රභේද විසිපහක් හෝ ඊට වැඩි ගණනක් භාවිත කිරීම", "දීර්ඝ විස්තරාත්මක ඡේදයක් කුඩා අකුරින් ඇතුළත් කිරීම", "හොඳ ලාංඡනයක් කළු-සුදු පැහැයෙන් කුඩා කළ විට පවා තම අනන්‍යතාව නොනැසී පවතී."),
        q("පොත් කවර (Book Cover) සහ සුබ පැතුම්පත් නිර්මාණයේදී 'අක්ෂර වින්‍යාසය' (Typography) වැදගත් වන්නේ කෙසේද?", "අකුරු හැඩය හා පරතරය තේමාවට ගැළපෙන සේ තේරීමෙන්", "සියලුම වර්ගයේ පොත් සඳහා එකම අකුරු හැඩය යෙදීමෙන්", "සිරස්තල කියවීමට අපහසු වන තරමට අකුරු පැටලවීමෙන්", "කවරයේ පොතේ නම හෝ කර්තෘ නම සම්පූර්ණයෙන් නොලිවීමෙන්", "ළමා පොතකට සෙල්ලක්කාර වටකුරු අකුරුද, ඉතිහාස පොතකට ගෞරවනීය සම්භාව්‍ය අකුරුද යෙදීම සුදුසුය."),
        q("ප්‍රායෝගික චිත්‍ර ඇඳීමේදී 'නිශ්චල ජීව චිත්‍රයක්' (Still Life) සැකසීමේදී හා ඇඳීමේදී වැදගත් වන මූලික පියවර කුමක්ද?", "විස්තරයට පෙර සමස්ත අනුපාත හා සැකිල්ල ලකුණු කිරීම", "සැලසුමකින් තොරව එක් කොනක සිට තද කළු තාන ගෑම", "සිතුවමේ මැද ඇති වස්තුව සම්පූර්ණයෙන් මකා දැමීම", "අවසන් මොහොතේදී ප්‍රධාන වස්තුවේ පිහිටීම වෙනස් කිරීම", "මුලින්ම මූලික ජ්‍යාමිතික හැඩ හා අනුපාත ලකුණු කර පසුව විස්තර හා තානය එක් කළ යුතුය."),
        q("කෞතුකාගාර හා පැරණි විහාර බිතුසිතුවම් සංරක්ෂණය (Art Conservation) කිරීමේදී පුරාවිද්‍යා සංරක්ෂකයන් අනුගමනය කරන ප්‍රධාන ප්‍රතිපත්තිය කුමක්ද?", "මුල් අනන්‍යතාව නොනසා ආපසු හැරවිය හැකි ද්‍රව්‍ය යෙදීම", "පැරණි සිතුවම සම්පූර්ණයෙන් සූරා අලුත් තීන්ත ගෑම", "බිත්ති මත නවීන ඇක්‍රිලික් ප්ලාස්ටික් ස්තර ඇලවීම", "වතුර හා සබන් යොදා බිතුසිතුවම් තදින් සෝදා හැරීම", "අලුතින් සම්පූර්ණ කර ඇඳීම වෙනුවට ඇති කොටස දිරා යාමෙන් වැළැක්වීම සංරක්ෂණයේ ප්‍රධාන නියමයයි."),
        q("ජල සායම් සිතුවම් ඇඳීමේදී සාමාන්‍යයෙන් වර්ණ ආලේප කරන නිවැරදි අනුපිළිවෙළ කුමක්ද?", "ළා වර්ණවලින් අරඹා තද වර්ණ හා විස්තර දක්වා යාම", "තද කළු පැහැයෙන් අරඹා සුදු පැහැය අවසානයේ උඩින් ගෑම", "සිතුවමේ මැද කොටස පමණක් තද රතු පැහැයෙන් වැසීම", "කිසිදු අනුපිළිවෙළකින් තොරව ඕනෑම තැනකින් ඇරඹීම", "විනිවිද පෙනෙන නිසා තද වර්ණ යට තැබුවහොත් ළා වර්ණවලින් ඒවා වැසිය නොහැකිය."),
        q("තෙල් සායම් හෝ ඇක්‍රිලික් (පාරාන්ධ වර්ණ) ඇඳීමේදී බොහෝ විට භාවිත කරන සාමාන්‍ය අනුපිළිවෙළ කුමක්ද?", "අඳුරු මධ්‍යම තානයන්ගෙන් අරඹා උච්ච ආලෝකය උඩින් යෙදීම", "සුදු කඩදාසිය ආලෝකය ලෙස ඉතිරි කර වතුර ඉස පැතිරවීම", "තෙත් කළ කඩදාසිය මත විනිවිද පෙනෙන ළා වොෂ් දැමීම", "ඉටි පැස්ටල් රේඛා ඇඳ පසුව ජල සායම් තීන්ත ආලේප කිරීම", "පාරාන්ධ තීන්ත මගින් යට අඳුරු ස්තර පහසුවෙන් ආවරණය කර ආලෝකය ඉස්මතු කළ හැකිය."),
        q("අ.පො.ස. සාමාන්‍ය පෙළ චිත්‍ර කලා විභාගයේ 'ප්‍රායෝගික අංශයේදී' සිසුන්ගෙන් බලාපොරොත්තු වන ප්‍රධාන කුසලතා කවරේද?", "වස්තු නිරීක්ෂණය, සංයුතික නිර්මාණ හා මෝස්තර ඇඳීම", "වීජ ගණිත සමීකරණ හා ජ්‍යාමිතික ප්‍රමේය සාධනය කිරීම", "පරිගණක දෘඩාංග හා විද්‍යුත් පරිපථ අලුත්වැඩියා කිරීම", "සාම්ප්‍රදායික කෘෂිකාර්මික බෝග වගා ක්‍රම විස්තර කිරීම", "සෞන්දර්ය න්‍යාය ප්‍රායෝගිකව භාවිත කර නිර්මාණාත්මක දෘශ්‍ය කෘති බිහි කිරීම අපේක්ෂිතය."),
        q("වීදුරු හෝ දිලිසෙන පිඟන් භාණ්ඩයක් නිශ්චල ජීව චිත්‍රයක් ලෙස ඇඳීමේදී එහි විනිවිද පෙනෙන බව හා දිලිසීම මවන්නේ කෙසේද?", "තියුණු සුදු ආලෝක ලප හා පසුබිම විකෘතිව පෙනීම දැක්වීමෙන්", "මුළු වීදුරු බඳුනම ඝන සුදු පෝස්ටර් තීන්තයෙන් වැසීමෙන්", "මතුපිට වයනය ඉතා රළු හා කළු අඟුරු පැහැයෙන් ඇඳීමෙන්", "සෙවණැලි හා පරාවර්තන ඉවත් කර පැතලි සමෝච්ඡයක් පමණක් ඇඳීමෙන්", "වීදුරු මතුපිට පරාවර්තන ආලෝකයේ තියුණු බව සුමට බව සහ විනිවිද පෙනෙන ස්වභාවය තහවුරු කරයි.")
    )
}
